const fs=require('fs');
const path=require('path');
const root=path.resolve(__dirname,'../..');
const api=fs.readFileSync(path.join(root,'functions/surveyor-api/src/main.js'),'utf8');
const save=fs.readFileSync(path.join(root,'functions/surveyor-save/src/main.js'),'utf8');
const cloud=fs.readFileSync(path.join(root,'assets/js/features/cloud/app.js'),'utf8');
const page=fs.readFileSync(path.join(root,'nuvem/index.html'),'utf8');
const css=fs.readFileSync(path.join(root,'assets/css/core/ui.css'),'utf8');
const ok=(v,m)=>{if(!v)throw new Error(m);console.log('OK:',m)};
ok(/const APP_VERSION = '[^']+'/.test(api),'API mantém marcador de versão sem fixar release antiga');
ok(api.includes('migratedFromStandaloneUserId') && api.includes('authorNames = new Map()'),'API recupera autor de projetos legados/migrados');
ok(api.includes('getAppwriteUserById(userId)'),'API resolve o nome do criador pelo Appwrite');
ok(api.includes('createdByName: String(currentMetadata.createdByName || projectMetadata.createdByName || memberCreatorName'),'migração preserva nome do subusuário criador');
ok(save.includes('createdByName: String(storedMetadata.createdByName'),'Save expõe autoria no projeto retornado');
ok(cloud.includes('Feito por: <b>${escapeHtml(project.createdByName)}</b>'),'card mostra Feito por com o criador real');
ok(!cloud.includes('Última edição por ${escapeHtml(project.lastSavedByName)}'),'card não confunde autoria com última edição');
ok(css.includes('.project-created-by'),'CSS exibe autoria abaixo do proprietário');
ok(page.includes('project-author-0829'),'Projetos usa cache-bust novo');
console.log('PASS: projetos compartilhados exibem quem realmente criou cada projeto.');
